import"./modulepreload-polyfill-Dezn_h7o.js";/* empty css               */import"./proteger-pagina-CCLhLS-N.js";import{t as e}from"./config-DPSuE5lU.js";document.querySelector(`#redefinir-form`).addEventListener(`submit`,async t=>{t.preventDefault();let n=new URLSearchParams(window.location.search).get(`token`),r=document.querySelector(`#nova-senha`).value;if(r!==document.querySelector(`#confirmar-senha`).value){alert(`As senhas não coincidem!`);return}try{let t=await fetch(`${e}/redefinir-senha`,{method:`POST`,headers:{"Content-Type":`application/json`},body:JSON.stringify({token:n,novaSenha:r})});if(t.ok)alert(`Senha redefinida com sucesso!`),window.location.href=`/index.html`;else{let e=await t.json();alert(`Erro: ${e.message}`)}}catch{alert(`Erro ao conectar ao servidor.`)}});